from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-21' and end_date = '2025-04-21')
and start_date = '2025-04-21' and end_date = '2025-04-21'

/* cppi::32818288e282d3e8edcf7adb21e52c7a668c17f60209f5435165ce6de279ce51 */
select business_date as date_, security_id, 'SP500_30' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-26' and business_date <= date '2025-06-26' and weight_ndo>0 and id_cppib_index = 'SP500_30_GR_USD_0_0' and security_id is not null

